    int fd2 = open("data.txt", O_RDONLY);   /* separate open file description */
    int fd3 = dup(fd1);                     /* shares description with fd1 */
    write(fd1, "ABCDEFGHIJ", 10);
    show("fd1", fd1);
    show("fd2", fd2);
    show("fd3", fd3);
    if (fork() == 0) {                      /* child inherits the descriptor table */
