import java.io.FileInputStream;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;

public class FdLeak {
    private static final List<FileInputStream> LEAKED = new ArrayList<>();

    // Bug: the stream is never closed, so each call leaks one descriptor.
    static String readConfig(Path p) throws IOException {
        FileInputStream in = new FileInputStream(p.toFile());
        LEAKED.add(in);               // simulates a reference kept by a pool or listener
        return new String(in.readAllBytes());
    }

    // Fix: Files.readString opens and closes the descriptor internally.
    static String readConfigFixed(Path p) throws IOException {
        return Files.readString(p);
    }

    public static void main(String[] args) throws Exception {
        Path p = Path.of("/etc/hostname");
        boolean fixed = args.length > 0 && args[0].equals("fixed");
        long pid = ProcessHandle.current().pid();
        for (int i = 1; i <= 400; i++) {
            try {
                if (fixed) readConfigFixed(p); else readConfig(p);
            } catch (IOException e) {
                System.out.println("call " + i + " failed: " + e.getMessage());
                System.out.println("pid " + pid + ", leaked streams: " + LEAKED.size());
                Thread.sleep(20000);      // keep the process alive for inspection
                return;
            }
        }
        System.out.println("all calls succeeded; open descriptors: "
                + Path.of("/proc/" + pid + "/fd").toFile().list().length);
    }
}

import java.io.IOException;
import java.nio.ByteBuffer;
import java.nio.channels.FileChannel;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;

public class FsyncLoop {
    public static void main(String[] args) throws IOException {
        long end = System.nanoTime() + Long.parseLong(args[1]) * 1_000_000_000L;
        try (FileChannel ch = FileChannel.open(Path.of(args[0]), StandardOpenOption.CREATE,
                StandardOpenOption.WRITE, StandardOpenOption.TRUNCATE_EXISTING)) {
            ByteBuffer buf = ByteBuffer.allocate(64 * 1024);
            long n = 0, worst = 0;
            while (System.nanoTime() < end) {
                buf.clear();
                ch.write(buf);
                long t = System.nanoTime();
                ch.force(true);
                worst = Math.max(worst, System.nanoTime() - t);
                n++;
                if (n % 4096 == 0) ch.truncate(0).position(0);   // cap file at 256 MiB
            }
            System.out.printf("fsync calls: %d, worst fsync: %.1f ms%n", n, worst / 1e6);
        }
    }
}

import java.io.IOException;
import java.nio.ByteBuffer;
import java.nio.channels.FileChannel;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;

public class FsyncCost {
    public static void main(String[] args) throws IOException {
        Path dir = Path.of(args[0]);
        int n = Integer.parseInt(args[1]);
        for (String mode : new String[] {"buffered", "force(false)", "force(true)"}) {
            Path p = dir.resolve("fsync-test.bin");
            try (FileChannel ch = FileChannel.open(p, StandardOpenOption.CREATE,
                    StandardOpenOption.WRITE, StandardOpenOption.TRUNCATE_EXISTING)) {
                ByteBuffer buf = ByteBuffer.allocate(4096);
                long t0 = System.nanoTime();
                for (int i = 0; i < n; i++) {
                    buf.clear();
                    ch.write(buf);
                    if (mode.equals("force(false)")) ch.force(false);
                    if (mode.equals("force(true)")) ch.force(true);
                }
                long us = (System.nanoTime() - t0) / 1000;
                System.out.printf("%-13s %5d writes of 4 KiB: total %8d us, %8.1f us/write%n",
                        mode, n, us, us / (double) n);
            }
            Files.delete(p);
        }
    }
}

import java.io.IOException;
import java.nio.ByteBuffer;
import java.nio.channels.FileChannel;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.nio.file.StandardOpenOption;

public class AtomicWrite {
    /** Replaces target with new content so that a crash leaves either the old or the new file. */
    static void replace(Path target, String content) throws IOException {
        Path dir = target.toAbsolutePath().getParent();
        Path tmp = Files.createTempFile(dir, "cfg", ".tmp");
        try (FileChannel ch = FileChannel.open(tmp, StandardOpenOption.WRITE)) {
            ch.write(ByteBuffer.wrap(content.getBytes(StandardCharsets.UTF_8)));
            ch.force(true);                                   // 1. data durable before the rename
        }
        Files.move(tmp, target, StandardCopyOption.ATOMIC_MOVE,
                StandardCopyOption.REPLACE_EXISTING);         // 2. atomic switch of the name
        try (FileChannel d = FileChannel.open(dir, StandardOpenOption.READ)) {
            d.force(true);                                    // 3. directory entry durable
        }
    }

    public static void main(String[] args) throws IOException {
        Path target = Path.of(args[0]);
        replace(target, "version=1\n");
        replace(target, "version=2\n");
        System.out.print(Files.readString(target));
        try (var names = Files.list(target.toAbsolutePath().getParent())) {
            names.forEach(p -> System.out.println("entry: " + p.getFileName()));
        }
    }
}

import java.io.IOException;
import java.nio.ByteBuffer;
import java.nio.channels.FileChannel;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import java.util.Arrays;

public class FsyncLatency {
    public static void main(String[] args) throws IOException {
        long end = System.nanoTime() + Long.parseLong(args[1]) * 1_000_000_000L;
        long[] lat = new long[200_000];
        int n = 0;
        try (FileChannel ch = FileChannel.open(Path.of(args[0]), StandardOpenOption.CREATE,
                StandardOpenOption.WRITE, StandardOpenOption.TRUNCATE_EXISTING)) {
            ByteBuffer buf = ByteBuffer.allocate(4096);
            while (System.nanoTime() < end && n < lat.length) {
                buf.clear();
                ch.write(buf);
                long t = System.nanoTime();
                ch.force(true);
                lat[n++] = System.nanoTime() - t;
                if (n % 2048 == 0) ch.truncate(0).position(0);
                try { Thread.sleep(2); } catch (InterruptedException e) { return; }
            }
        }
        long[] s = Arrays.copyOf(lat, n);
        Arrays.sort(s);
        System.out.printf("n=%d  p50=%.2f ms  p99=%.2f ms  max=%.2f ms%n", n,
                s[n / 2] / 1e6, s[(int) (n * 0.99)] / 1e6, s[n - 1] / 1e6);
    }
}

#include <arpa/inet.h>
#include <errno.h>
#include <fcntl.h>
#include <netinet/in.h>
#include <stdio.h>
#include <stdlib.h>
#include <sys/epoll.h>
#include <sys/socket.h>
#include <unistd.h>

#define MAX_EVENTS 64

static void set_nonblocking(int fd) {
    fcntl(fd, F_SETFL, fcntl(fd, F_GETFL, 0) | O_NONBLOCK);
}

int main(int argc, char **argv) {
    int port = argc > 1 ? atoi(argv[1]) : 20501;
    int lfd = socket(AF_INET, SOCK_STREAM, 0);
    int one = 1;
    setsockopt(lfd, SOL_SOCKET, SO_REUSEADDR, &one, sizeof one);
    struct sockaddr_in a = { .sin_family = AF_INET, .sin_port = htons(port),
                             .sin_addr.s_addr = htonl(INADDR_LOOPBACK) };
    if (bind(lfd, (struct sockaddr *)&a, sizeof a) < 0 || listen(lfd, 128) < 0) {
        perror("bind/listen");
        return 1;
    }
    set_nonblocking(lfd);
    int ep = epoll_create1(0);
    struct epoll_event ev = { .events = EPOLLIN, .data.fd = lfd };
    epoll_ctl(ep, EPOLL_CTL_ADD, lfd, &ev);
    struct epoll_event events[MAX_EVENTS];
    for (;;) {
        int n = epoll_wait(ep, events, MAX_EVENTS, -1);
        for (int i = 0; i < n; i++) {
            int fd = events[i].data.fd;
            if (fd == lfd) {                       /* new connection(s) */
                int c;
                while ((c = accept(lfd, NULL, NULL)) >= 0) {
                    set_nonblocking(c);
                    struct epoll_event ce = { .events = EPOLLIN, .data.fd = c };
                    epoll_ctl(ep, EPOLL_CTL_ADD, c, &ce);
                }
            } else {                               /* readable client socket */
                char buf[4096];
                ssize_t r = read(fd, buf, sizeof buf);
                if (r > 0) {
                    if (write(fd, buf, r) < 0) perror("write");
                } else if (r == 0 || errno != EAGAIN) {
                    close(fd);                     /* close removes it from the epoll set */
                }
            }
        }
    }
}

